/**
 * @param {number[]} nums
 * @return {number}
 */
var minMirrorPairDistance = function(nums) {
    const map = new Map();
    let min = Infinity;

    for (let i = 0; i < nums.length; i++) {
        const pos = map.get(nums[i]) ?? -1;
        if (pos > -1) {
            min = Math.min(min, i - pos);
        }

        const reverse = reverseNum(nums[i]);
        map.set(reverse, i);
    }

    if (min === Infinity) {
        return -1;
    }

    return min;
};

const reverseNum = (num) => {
    let res = 0;

    while (num > 0) {
        res = res * 10 + (num % 10);
        num = Math.floor(num / 10);
    }

    return res;
};
